nev='CCSDS_ldpc_n128_k64' %[output:2ed6d2bd]
hold on %[output:06944098]
load([nev,'_Sync_16QAM'])
[vx, vy]   = filterValidPoints(snrRange, ber);
semilogy(vx,vy,'yo--'); %[output:06944098]
load([nev,'_AM4_16'])
[vx, vy]   = filterValidPoints(snrRange, ber);
semilogy(vx,vy,'bo-'); %[output:06944098]
load([nev,'_AM4_16_Bidir'])
[vx, vy]   = filterValidPoints(snrRange, ber);
semilogy(vx,vy,'go-'); %[output:06944098]
load([nev,'_AM4_16_Gray']);
[vx, vy]   = filterValidPoints(snrRange, ber);
semilogy(vx,vy,'co-'); %[output:06944098]
load([nev,'_AM4_16_Soft'])
[vx, vy]   = filterValidPoints(snrRange, ber);
semilogy(vx,vy,'mo-'); %[output:06944098]
hold off %[output:06944098]

function [vx, vy] = filterValidPoints(x, y)
mask = ~isnan(y) & ~isinf(y) & (y > 0);
vx = x(mask);
vy = y(mask);
end

